    imageAlt: "Hund wird gewogen für die korrekte Futtermenge",
    content: `## Warum das Körpergewicht entscheidend ist

Die Futtermenge sollte sich am Körpergewicht des Hundes orientieren — nicht an gefühlten Schätzungen oder den Empfehlungen auf der Packung. Jeder Hund hat einen individuellen Energiebedarf, der von Gewicht, Alter, Aktivität und Gesundheit bestimmt wird.

### Die Grundregel: 2-3% des Körpergewichts

Als Faustregel gilt:
- **Ruhige Hunde:** 2% des Körpergewichts pro Tag
- **Normal aktive Hunde:** 2,5% des Körpergewichts pro Tag
- **Sehr aktive Hunde:** 3% des Körpergewichts pro Tag

Beispiel: Ein 20kg schwerer, normal aktiver Hund benötigt etwa 500g Futter pro Tag (20kg × 2,5% = 0,5kg = 500g).

### Wichtige Unterscheidung: Idealgewicht vs. Istgewicht

**Idealgewicht:**
- Das Gewicht, bei dem der Hund optimal ist
- Rippen fühlen, aber nicht sehen
- Taille von oben erkennbar
- Bauch leicht aufgezogen

**Istgewicht:**
- Das aktuelle Gewicht auf der Waage
- Kann über oder unter dem Ideal liegen
- Nicht immer die Basis für die Futterberechnung

Bei übergewichtigen Hunden immer nach Idealgewicht füttern, nicht nach Istgewicht!

### Faktoren, die den Bedarf beeinflussen

**Lebensphase:**
- **Welpen:** 3-6% (Wachstum benötigt viel Energie)
- **Adult:** 2-3% (Erhaltung)
- **Senior:** 1,5-2,5% (langsamer Stoffwechsel)

**Aktivitätslevel:**
- **Couch-Potato:** 1,5-2%
- **Normal aktiv:** 2-2,5%
- **Arbeitshund:** 3-5%
- **Sportler:** 4-6%

**Gesundheit:**
- **Krankheit:** Mehr oder weniger je nach Erkrankung
- **Genesung:** Oft mehr für Heilung
- **Diät:** Weniger für Gewichtsverlust
- **Kastration:** Oft 20-30% weniger Bedarf

**Rasse:**
- **Kleine Rassen:** Höherer Stoffwechsel pro kg
- **Große Rassen:** Langsamerer Stoffwechsel
- **Mittelrassen:** Durchschnittlicher Bedarf

### Praktische Berechnungsbeispiele

**Beispiel 1: Normal aktiver Hund**
- Gewicht: 25kg
- Aktivität: Normal (2,5%)
- Tagesmenge: 25kg × 0,025 = 625g

**Beispiel 2: Welpen**
- Gewicht: 10kg
- Aktivität: Hoch (5%)
- Tagesmenge: 10kg × 0,05 = 500g

**Beispiel 3: Senior, übergewichtig**
- Istgewicht: 30kg
- Idealgewicht: 25kg
- Aktivität: Niedrig (1,5%)
- Tagesmenge: 25kg × 0,015 = 375g

### Anpassung über die Zeit

Der Energiebedarf ändert sich:
- **Saisonal:** Mehr im Winter, weniger im Sommer
- **Alter:** Langsamer mit den Jahren
- **Gesundheit:** Bei Krankheit oder Genesung
- **Aktivität:** Mit mehr oder weniger Bewegung

Regelmäßige Anpassungen sind notwendig für optimale Fütterung.

### Wie du das Idealgewicht bestimmst

**Body Condition Score (BCS):**
- 1-3: Unterweight (zu dünn)
- 4-5: Ideal (optimal)
- 6-9: Overweight (zu dick)

**Körperliche Merkmale:**
- Rippen fühlen, aber nicht sehen (ideal)
- Taille von oben erkennbar (ideal)
- Bauch leicht aufgezogen (ideal)
- Keine Fettpolster über Rippen (ideal)

Bei Unsicherheit den Tierarzt konsultieren.

### Häufige Fehler bei der Futterberechnung

**Fehler 1: Nach Istgewicht füttern**
- Bei übergewichtigen Hunden das Idealgewicht nehmen
- Sonst wird Übergewicht zementiert

**Fehler 2: Packungsangaben blind folgen**
- Diese sind oft zu hoch
- Individuell anpassen

**Fehler 3: Leckerlis nicht einrechnen**
- Snacks machen bis zu 10% der Kalorien aus
- Von der Tagesration abziehen

**Fehler 4: Nicht regelmäßig anpassen**
- Bedarf ändert sich über Zeit
- Regelmäßig überprüfen

### Spezielle Situationen

**Nach Kastration:**
- Bedarf sinkt oft um 20-30%
- Futtermenge reduzieren oder Light-Futter
- Gewicht regelmäßig kontrollieren

**Bei Krankheit:**
- Je nach Erkrankung mehr oder weniger
- Mit Tierarzt besprechen
- Spezielles Diätfutter möglich

**Während der Trächtigkeit:**
- Bedarf steigt im Verlauf
- Spezielles Welpenfutter
- Mit Tierarzt absprechen

### Monitoring und Anpassung

**Wöchentliche Kontrolle:**
- Gewicht messen
- BCS überprüfen
- Futtermenge anpassen

**Monatliche Überprüfung:**
- Langfristige Trends
- Futterart evaluieren
- Gesundheitszustand prüfen

**Bei Veränderungen:**
- Aktivitätsänderung
- Gesundheitsänderung
- Lebensphasenwechsel

### Praktische Tipps für die tägliche Fütterung

1. **Waage nutzen:** Täglich oder wöchentlich wiegen
2. **Messbecher:** Genau dosieren, nicht schätzen
3. **Tagebuch:** Futtermenge und Gewicht notieren
4. **Regelmäßigkeit:** Gleiche Zeiten, gleiche Mengen
5. **Flexibilität:** Bei Bedarf anpassen

### Zusammenfassung

Die Futtermenge sollte sich am Idealgewicht orientieren, nicht am Istgewicht. Berücksichtige Lebensphase, Aktivität und Gesundheit. Regelmäßige Kontrolle und Anpassung sind der Schlüssel zu optimaler Fütterung.`,
